chkDarkTheme.setOnPreferenceChangeListener(new Preference.OnPreferenceChangeListener() {
    @Override
    public boolean onPreferenceChange(Preference preference, Object newValue) {
        // Recreate this Activity to apply the new theme, but leave the rest of the back
        // stack (e.g., GpsTestActivity) intact so the user can still return to it.
        // Activities lower in the back stack apply the new theme when they are resumed.
        // Post the recreate() so the new preference value is persisted first.
        new Handler(Looper.getMainLooper()).post(new Runnable() {
            @Override
            public void run() {
                recreate();
            }
        });
        return true;
    }
});

