private SensorManager mSensorManager;

/**
 * Holds the value of the dark theme preference that is currently applied to this Activity, so
 * we can detect a change made in the Settings and re-create this Activity when it is resumed
 */
private boolean mUseDarkTheme = false;

/** Called when the activity is first created. */
@Override
public void onCreate(Bundle savedInstanceState) {
    // Set theme
    if (Application.getPrefs().getBoolean(getString(R.string.pref_key_dark_theme), false)) {
        mUseDarkTheme = true;
        setTheme(R.style.AppTheme_Dark_NoActionBar);
    }

    if (GpsTestUtil.isGnssStatusListenerSupported()) {
        checkNavMessageOutput(settings);
    }

    // If the user changed the theme in the Settings, re-create this Activity so the new theme
    // is applied here too.  This is done last so the listeners added above are balanced by the
    // removals in onPause() when this Activity is destroyed and re-created.
    if (mUseDarkTheme != settings
            .getBoolean(getString(R.string.pref_key_dark_theme), false)) {
        recreate();
    }
}

