319	        switch (item) {
320	            case NAVDRAWER_ITEM_STATUS:
321	                if (mCurrentNavDrawerPosition != NAVDRAWER_ITEM_STATUS) {
322	                    showStatusFragment();
323	                    mCurrentNavDrawerPosition = item;
324	                }
325	                break;
326	            case NAVDRAWER_ITEM_MAP:
327	                if (mCurrentNavDrawerPosition != NAVDRAWER_ITEM_MAP) {
328	                    showMapFragment();
329	                    mCurrentNavDrawerPosition = item;
330	                }
331	                break;
332	            case NAVDRAWER_ITEM_SKY:
333	                if (mCurrentNavDrawerPosition != NAVDRAWER_ITEM_SKY) {
334	                    showSkyFragment();
335	                    mCurrentNavDrawerPosition = item;
336	                }
337	                break;
338	            case NAVDRAWER_ITEM_INJECT_XTRA_DATA:
339	                forceXtraInjection();
340	                break;
341	            case NAVDRAWER_ITEM_INJECT_TIME_DATA:
342	                forceTimeInjection();
343	                break;
344	            case NAVDRAWER_ITEM_CLEAR_AIDING_DATA:
345	                deleteAidingData();
346	                break;
347	            case NAVDRAWER_ITEM_SETTINGS:
348	                startActivity(new Intent(this, Preferences.class));
349	                break;
350	            case NAVDRAWER_ITEM_HELP:
351	                showDialog(HELP_DIALOG);
352	                break;
353	            case NAVDRAWER_ITEM_OPEN_SOURCE:
354	                Intent i = new Intent(Intent.ACTION_VIEW);
355	                i.setData(Uri.parse(getString(R.string.open_source_github)));
356	                startActivity(i);
357	                break;
358	        }
359	        invalidateOptionsMenu();
