497	    private void deleteAidingData() {
498	        // If GPS is currently running, stop it
499	        boolean lastStartState = mStarted;
500	        if (mStarted) {
501	            gpsStop();
502	        }
503	        boolean success = sendExtraCommand(getString(R.string.delete_aiding_data_command));
504	        if (success) {
505	            Toast.makeText(this, getString(R.string.delete_aiding_data_success),
506	                    Toast.LENGTH_SHORT).show();
507	        } else {
508	            Toast.makeText(this, getString(R.string.delete_aiding_data_failure),
509	                    Toast.LENGTH_SHORT).show();
510	        }
511	
512	        if (lastStartState) {
513	            Handler h = new Handler();
514	            // Restart the GPS, if it was previously started, with a slight delay,
515	            // to refresh the assistance data
516	            h.postDelayed(new Runnable() {
517	                public void run() {
518	                    gpsStart();
519	                }
520	            }, 500);
521	        }
522	    }
