542	    private synchronized void gpsStart() {
543	        if (!mStarted) {
544	            mLocationManager
545	                    .requestLocationUpdates(mProvider.getName(), minTime, minDistance, this);
546	            mStarted = true;
547	
548	            // Show Toast only if the user has set minTime or minDistance to something other than default values
549	            if (minTime != (long) (Double.valueOf(getString(R.string.pref_gps_min_time_default_sec))
550	                    * SECONDS_TO_MILLISECONDS) ||
551	                    minDistance != Float
552	                            .valueOf(getString(R.string.pref_gps_min_distance_default_meters))) {
553	                Toast.makeText(this, String.format(getString(R.string.gps_set_location_listener),
554	                        String.valueOf((double) minTime / SECONDS_TO_MILLISECONDS),
555	                        String.valueOf(minDistance)), Toast.LENGTH_SHORT).show();
556	            }
557	
558	            // Show the indeterminate progress bar on the action bar until first GPS status is shown
559	            setSupportProgressBarIndeterminateVisibility(Boolean.TRUE);
560	
561	            // Reset the options menu to trigger updates to action bar menu items
562	            invalidateOptionsMenu();
563	        }
564	        for (GpsTestListener listener : mGpsTestListeners) {
565	            listener.gpsStart();
566	        }
567	    }
568	
569	    private synchronized void gpsStop() {
570	        if (mStarted) {
571	            mLocationManager.removeUpdates(this);
572	            mStarted = false;
573	            // Stop progress bar
574	            setSupportProgressBarIndeterminateVisibility(Boolean.FALSE);
575	
576	            // Reset the options menu to trigger updates to action bar menu items
577	            invalidateOptionsMenu();
578	        }
579	        for (GpsTestListener listener : mGpsTestListeners) {
580	            listener.gpsStop();
581	        }
582	    }
