1057	    @TargetApi(Build.VERSION_CODES.GINGERBREAD)
1058	    @Override
1059	    public void onSensorChanged(SensorEvent event) {
1060	
1061	        double orientation = Double.NaN;
1062	        double tilt = Double.NaN;
1063	
1064	        switch (event.sensor.getType()) {
1065	            case Sensor.TYPE_ROTATION_VECTOR:
1066	                // Modern rotation vector sensors
1067	                if (!mTruncateVector) {
1068	                    try {
1069	                        SensorManager.getRotationMatrixFromVector(mRotationMatrix, event.values);
1070	                    } catch (IllegalArgumentException e) {
1071	                        // On some Samsung devices, an exception is thrown if this vector > 4 (see #39)
1072	                        // Truncate the array, since we can deal with only the first four values
1073	                        Log.e(TAG, "Samsung device error? Will truncate vectors - " + e);
1074	                        mTruncateVector = true;
1075	                        // Do the truncation here the first time the exception occurs
1076	                        getRotationMatrixFromTruncatedVector(event.values);
1077	                    }
1078	                } else {
1079	                    // Truncate the array to avoid the exception on some devices (see #39)
1080	                    getRotationMatrixFromTruncatedVector(event.values);
1081	                }
1082	
1083	                int rot = getWindowManager().getDefaultDisplay().getRotation();
1084	                switch (rot) {
1085	                    case Surface.ROTATION_0:
1086	                        // No orientation change, use default coordinate system
1087	                        SensorManager.getOrientation(mRotationMatrix, mValues);
1088	                        // Log.d(TAG, "Rotation-0");
1089	                        break;
1090	                    case Surface.ROTATION_90:
1091	                        // Log.d(TAG, "Rotation-90");
1092	                        SensorManager.remapCoordinateSystem(mRotationMatrix, SensorManager.AXIS_Y,
1093	                                SensorManager.AXIS_MINUS_X, mRemappedMatrix);
1094	                        SensorManager.getOrientation(mRemappedMatrix, mValues);
1095	                        break;
1096	                    case Surface.ROTATION_180:
1097	                        // Log.d(TAG, "Rotation-180");
1098	                        SensorManager
1099	                                .remapCoordinateSystem(mRotationMatrix, SensorManager.AXIS_MINUS_X,
1100	                                        SensorManager.AXIS_MINUS_Y, mRemappedMatrix);
1101	                        SensorManager.getOrientation(mRemappedMatrix, mValues);
1102	                        break;
1103	                    case Surface.ROTATION_270:
1104	                        // Log.d(TAG, "Rotation-270");
1105	                        SensorManager
1106	                                .remapCoordinateSystem(mRotationMatrix, SensorManager.AXIS_MINUS_Y,
1107	                                        SensorManager.AXIS_X, mRemappedMatrix);
1108	                        SensorManager.getOrientation(mRemappedMatrix, mValues);
1109	                        break;
1110	                    default:
1111	                        // This shouldn't happen - assume default orientation
1112	                        SensorManager.getOrientation(mRotationMatrix, mValues);
1113	                        // Log.d(TAG, "Rotation-Unknown");
1114	                        break;
1115	                }
1116	                orientation = Math.toDegrees(mValues[0]);  // azimuth
1117	                tilt = Math.toDegrees(mValues[1]);
1118	                break;
1119	            case Sensor.TYPE_ORIENTATION:
1120	                // Legacy orientation sensors
1121	                orientation = event.values[0];
1122	                break;
1123	            default:
1124	                // A sensor we're not using, so return
1125	                return;
1126	        }
1127	
1128	        // Correct for true north, if preference is set
1129	        if (mFaceTrueNorth && mGeomagneticField != null) {
1130	            orientation += mGeomagneticField.getDeclination();
1131	            // Make sure value is between 0-360
1132	            orientation = MathUtils.mod((float) orientation, 360.0f);
1133	        }
1134	
1135	        for (GpsTestListener listener : mGpsTestListeners) {
1136	            listener.onOrientationChanged(orientation, tilt);
1137	        }
1138	    }
1139	
1140	    @TargetApi(Build.VERSION_CODES.GINGERBREAD)
1141	    private void getRotationMatrixFromTruncatedVector(float[] vector) {
1142	        System.arraycopy(vector, 0, mTruncatedRotationVector, 0, 4);
1143	        SensorManager.getRotationMatrixFromVector(mRotationMatrix, mTruncatedRotationVector);
1144	    }
