201	    public void setUp(int fragmentId, DrawerLayout drawerLayout) {
202	        int selfItem = mCurrentSelectedPosition;
203	        mFragmentContainerView = getActivity().findViewById(fragmentId);
204	        mDrawerLayout = drawerLayout;
