211	        mDrawerLayout.setDrawerShadow(R.drawable.drawer_shadow, GravityCompat.START);
212	        ScrimInsetsScrollView navDrawer = mDrawerLayout.findViewById(R.id.navdrawer);
213	        if (selfItem == NAVDRAWER_ITEM_INVALID) {
214	            // do not show a nav drawer
215	            if (navDrawer != null) {
216	                ((ViewGroup) navDrawer.getParent()).removeView(navDrawer);
217	            }
218	            mDrawerLayout = null;
219	            return;
220	        }
221	
222	        // populate the nav drawer with the correct items
223	        populateNavDrawer();
224	
225	        ActionBar actionBar = getActionBar();
226	        actionBar.setDisplayHomeAsUpEnabled(true);
227	        actionBar.setHomeButtonEnabled(true);
228	
229	        // ActionBarDrawerToggle ties together the the proper interactions
230	        // between the navigation drawer and the action bar app icon.
231	        mDrawerToggle = new android.support.v7.app.ActionBarDrawerToggle(
232	                getActivity(),                    /* host Activity */
233	                mDrawerLayout,                    /* DrawerLayout object */
234	                R.string.navigation_drawer_open,  /* "open drawer" description for accessibility */
235	                R.string.navigation_drawer_close  /* "close drawer" description for accessibility */
236	        ) {
