251	                    return;
252	                }
253	
254	                getActivity().supportInvalidateOptionsMenu(); // calls onPrepareOptionsMenu()
255	            }
256	        };
257	
258	        // Defer code dependent on restoration of previous instance state.
259	        mDrawerLayout.post(new Runnable() {
260	            @Override
261	            public void run() {
262	                mDrawerToggle.syncState();
263	            }
