428	    private View makeNavDrawerItem(final int itemId, ViewGroup container) {
429	        boolean selected = mCurrentSelectedPosition == itemId;
430	        int layoutToInflate;
431	        if (itemId == NAVDRAWER_ITEM_SEPARATOR) {
432	            layoutToInflate = R.layout.navdrawer_separator;
433	        } else if (itemId == NAVDRAWER_ITEM_SEPARATOR_SPECIAL) {
434	            layoutToInflate = R.layout.navdrawer_separator_special;
435	        } else {
436	            layoutToInflate = R.layout.navdrawer_item;
437	        }
438	        View view = getActivity().getLayoutInflater().inflate(layoutToInflate, container, false);
439	
440	        if (isSeparator(itemId)) {
441	            // we are done
442	            UIUtils.setAccessibilityIgnore(view);
443	            return view;
444	        }
445	
446	        ImageView iconView = view.findViewById(R.id.icon);
447	        TextView titleView = view.findViewById(R.id.title);
448	        ImageView secondaryIconView = view.findViewById(R.id.secondary_icon);
449	        int iconId = itemId >= 0 && itemId < NAVDRAWER_ICON_RES_ID.length ?
450	                NAVDRAWER_ICON_RES_ID[itemId] : 0;
451	        int titleId = itemId >= 0 && itemId < NAVDRAWER_TITLE_RES_ID.length ?
452	                NAVDRAWER_TITLE_RES_ID[itemId] : 0;
453	        int secondaryIconId = itemId >= 0 && itemId < NAVDRAWER_ICON_SECONDARY_RES_ID.length ?
454	                NAVDRAWER_ICON_SECONDARY_RES_ID[itemId] : 0;
455	
456	        // set icon and text
457	        iconView.setVisibility(iconId > 0 ? View.VISIBLE : View.GONE);
458	        if (iconId > 0) {
459	            iconView.setImageResource(iconId);
460	        }
461	        titleView.setText(getString(titleId));
462	
463	        // Secondary icon
464	        secondaryIconView.setVisibility(secondaryIconId > 0 ? View.VISIBLE : View.GONE);
465	        if (secondaryIconId > 0) {
466	            secondaryIconView.setImageResource(secondaryIconId);
467	        }
468	
469	        formatNavDrawerItem(view, itemId, selected);
470	
471	        view.setOnClickListener(new View.OnClickListener() {
472	            @Override
473	            public void onClick(View v) {
474	                selectItem(itemId);
475	            }
476	        });
477	
478	        return view;
479	    }
