481	    private void formatNavDrawerItem(View view, int itemId, boolean selected) {
482	        if (isSeparator(itemId)) {
483	            // Don't do any formatting
484	            return;
485	        }
486	
487	        ImageView iconView = view.findViewById(R.id.icon);
488	        TextView titleView = view.findViewById(R.id.title);
489	        ImageView secondaryIconView = view.findViewById(R.id.secondary_icon);
490	
491	        /**
492	         * Configure its appearance according to whether or not it's selected.  Certain items
493	         * (e.g., Settings) don't get formatted upon selection, since they open a new activity.
494	         */
495	        if (selected) {
496	            if (isNewActivityItem(itemId)) {
497	                // Don't change any formatting, since this is a category that launches a new activity
498	                return;
499	            } else {
500	                // Show the category as highlighted by changing background, text, and icon color
501	                view.setSelected(true);
502	                titleView.setTextColor(
503	                        getResources().getColor(R.color.navdrawer_text_color_selected));
504	                iconView.setColorFilter(
505	                        getResources().getColor(R.color.navdrawer_icon_tint_selected));
506	                secondaryIconView.setColorFilter(
507	                        getResources().getColor(R.color.navdrawer_icon_tint_selected));
508	            }
509	        } else {
510	            // Show the category as not highlighted, if its not currently selected
511	            if (itemId != mCurrentSelectedPosition) {
512	                view.setSelected(false);
513	                if (Application.getPrefs().getBoolean(getString(R.string.pref_key_dark_theme), false)) {
514	                    // Dark theme
515	                    titleView.setTextColor(getResources().getColor(R.color.navdrawer_text_color_dark));
516	                    iconView.setColorFilter(getResources().getColor(R.color.navdrawer_icon_tint_dark));
517	                    secondaryIconView.setColorFilter(getResources().getColor(R.color.navdrawer_icon_tint_dark));
518	                } else {
519	                    // Light theme
520	                    titleView.setTextColor(getResources().getColor(R.color.navdrawer_text_color_light));
521	                    iconView.setColorFilter(getResources().getColor(R.color.navdrawer_icon_tint_light));
522	                    secondaryIconView.setColorFilter(getResources().getColor(R.color.navdrawer_icon_tint_light));
523	                }
524	            }
525	        }
526	    }
